/**
 * Content-Security-Policy builder for the Athlya member web app.
 *
 * Implements Req 25.3: every HTML response is served with a strict CSP
 * that uses a per-request nonce for inline `<script>` and `<style>` tags.
 * The nonce is generated by `src/lib/nonce.ts` in the Edge middleware,
 * stitched into this policy, emitted on the response, and mirrored into
 * the `x-nonce` request header so server components can reuse it when
 * rendering inline style blocks (e.g. the per-tenant brand color CSS).
 *
 * Cloudflare Turnstile origins (`https://challenges.cloudflare.com`) are
 * pre-whitelisted because task 10.2 wires Turnstile into the login /
 * register pages — keeping them in the policy now means the CSP won't
 * have to be revisited when that task lands.
 *
 * The policy intentionally:
 *  - forbids `frame-ancestors` entirely (redundant with the static
 *    `X-Frame-Options: DENY`, but belt-and-braces against older UAs);
 *  - disables `object-src` (no Flash / applets);
 *  - forces `upgrade-insecure-requests` so any stray `http://` asset is
 *    silently upgraded rather than blocked.
 *
 * @see Req 25.3, Req 25.4 — requirements.md
 *
 * Task 10.1.
 */

/**
 * Input parameters controlling the emitted CSP directives.
 *
 * `apiUrl` lets the policy whitelist the exact `connect-src` origin the
 * app talks to (the Hono edge API). We default to the same origin so
 * local dev works out-of-the-box when the API is proxied through Next.
 *
 * `reportUri`, when supplied, enables CSP violation reporting: browsers
 * will POST a JSON payload to that endpoint whenever a directive blocks
 * something. Unset by default so local dev and CI stay quiet; the proxy
 * reads it from `NEXT_PUBLIC_CSP_REPORT_URI` in production.
 *
 * `dev` toggles development-only relaxations. When `true`, the CSP
 * adds `'unsafe-eval'` to `script-src` so React's dev mode runtime can
 * reconstruct stack traces via `eval()` (it refuses to start without
 * it, surfacing as `eval() is not supported in this environment` in
 * the browser console). React production builds never call `eval()`,
 * so the flag MUST stay `false` outside of `next dev`.
 */
export interface CspOptions {
  readonly nonce: string;
  readonly apiUrl?: string;
  readonly reportUri?: string;
  readonly dev?: boolean;
  readonly isDev?: boolean;
}

const TURNSTILE_ORIGIN = 'https://challenges.cloudflare.com';

/**
 * Stable group name used by the `report-to` directive and the matching
 * `Report-To` response header. Exported so the proxy can reference the
 * same identifier without duplicating the literal.
 */
export const CSP_REPORT_GROUP = 'athlya-csp';

/**
 * Build the `Content-Security-Policy` header value for a single request.
 *
 * The nonce appears in both `script-src` and `style-src` so a single
 * value can gate inline scripts (e.g. Next.js runtime injection) and
 * inline styles (e.g. server-rendered brand-color CSS from task 15.2).
 *
 * Returns a single-line string — the middleware sets it verbatim on the
 * response. Whitespace between directives is normalised so the output
 * matches whatever tests assert against.
 */
export function generateCsp({ nonce, apiUrl, reportUri, dev, isDev }: CspOptions): string {
  if (nonce.length === 0) {
    throw new TypeError('generateCsp: nonce must be a non-empty string');
  }

  const connectExtras = apiUrl !== undefined && apiUrl.length > 0 ? ` ${apiUrl}` : '';

  // In development, React / Next.js inject runtime helpers that call
  // `eval()` to rebuild cross-frame stack traces. Production builds
  // never use `eval()`, so the relaxation is strictly scoped to
  // `next dev`. The guard is a runtime flag (NOT a build-time
  // constant) so `pnpm start` against a prod build emits a strict
  // policy even on localhost.
  const scriptSrcExtras = dev === true ? ` 'unsafe-eval'` : '';

  // In development, Next.js dev tools and font loading inject inline
  // styles without the nonce. CSP Level 2 ignores 'unsafe-inline' when
  // a nonce is present, so we must drop the nonce entirely from
  // style-src and rely solely on 'unsafe-inline' in dev.
  const styleSrc =
    isDev === true ? `style-src 'self' 'unsafe-inline'` : `style-src 'self' 'nonce-${nonce}'`;

  // Sprint-3 SP3.1 (Vague 31, audit finding S6-001) — production
  // CSP keeps `style-src 'self' 'nonce-...'` strict (blocks inline
  // <style> blocks that lack the nonce) but allows inline `style=""`
  // attributes via `style-src-attr 'unsafe-inline'`. Without this
  // directive, every `style={{ ... }}` JSX expression that React
  // serialises as `style="..."` on the HTML attribute would be
  // dropped by the browser in prod. The audit scanned the codebase
  // and found two such usages in `BrandingPreview` (per-tenant
  // branding pulls a hex colour from the studio config and applies
  // it inline). Refactoring those to CSS variables is on the
  // hardening backlog (S6-001 option 2) but not required to ship —
  // `style-src-attr 'unsafe-inline'` is the option-1 mitigation
  // recommended by the audit. The strict `style-src` directive
  // still gates inline blocks, so an XSS that injects
  // `<style>...</style>` is blocked.
  //
  // In dev we don't emit `style-src-attr` separately — the broad
  // `style-src 'unsafe-inline'` already covers attribute styles.
  const styleSrcAttr = isDev === true ? '' : `style-src-attr 'unsafe-inline'`;

  const directives: string[] = [
    `default-src 'self'`,
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${scriptSrcExtras} ${TURNSTILE_ORIGIN}`,
    styleSrc,
    ...(styleSrcAttr.length > 0 ? [styleSrcAttr] : []),
    `img-src 'self' data: blob:`,
    `font-src 'self' data:`,
    `connect-src 'self'${connectExtras} ${TURNSTILE_ORIGIN}`,
    `frame-src 'self' ${TURNSTILE_ORIGIN}`,
    `object-src 'none'`,
    `base-uri 'self'`,
    `form-action 'self'`,
    `frame-ancestors 'none'`,
    `upgrade-insecure-requests`,
  ];

  // Reporting directives are only emitted when an endpoint is
  // configured. `report-to` is the modern directive (Reporting API);
  // `report-uri` stays as a fallback for older browsers that still
  // honour it. Both are safe to emit simultaneously — browsers pick
  // the one they understand and ignore the other.
  if (reportUri !== undefined && reportUri.length > 0) {
    directives.push(`report-to ${CSP_REPORT_GROUP}`);
    directives.push(`report-uri ${reportUri}`);
  }

  return directives.join('; ');
}

/**
 * Build the `Report-To` response header value paired with the
 * `report-to` CSP directive. Returns `undefined` when no endpoint is
 * configured so the caller can skip emitting the header entirely.
 *
 * The payload format is defined by
 * https://www.w3.org/TR/reporting-1/#header. `max_age` is one day —
 * long enough to avoid a per-request round-trip, short enough that
 * a changed endpoint propagates within a working day.
 */
export function buildReportToHeader(reportUri: string | undefined): string | undefined {
  if (reportUri === undefined || reportUri.length === 0) return undefined;
  return JSON.stringify({
    group: CSP_REPORT_GROUP,
    max_age: 86_400,
    endpoints: [{ url: reportUri }],
  });
}
